content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-003

=== 用户原始指令 (query.txt) ===
整个电量监控的嘛,能看百分比,点能开省电,能读天气,红色警告加上

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个电量监控的嘛,能看百分比,点能开省电,能读天气,红色警告加上",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "device": {
      "battery": {
        "percent": {
          "type": "number",
          "description": "当前电量百分比数值，用于进度条。",
          "sampleValue": 18
        },
        "percentText": {
          "type": "string",
          "description": "当前电量百分比展示文本。",
          "sampleValue": "18%"
        },
        "alertLabel": {
          "type": "string",
          "description": "低电量红色警告标签。",
          "sampleValue": "红色警告"
        },
        "savingHint": {
          "type": "string",
          "description": "省电模式开启建议。",
          "sampleValue": "建议开启省电"
        }
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_electricity.png",
      "description": "电池图标，适合低电模式卡片中作为电量监控识别素材。"
    },
    {
      "src": "resources/base/media/icon_save_power.png",
      "description": "省电图标，适合低电模式卡片中作为省电入口视觉素材。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合展示多云或普通天气摘要。"
    }
  ]
}

